// Regression test (Step 2 of the pricing-integration audit, finding B1).
//
// Before the fix `quoteId` was generated by POST /pricing/quote and then never
// read: POST /orders re-priced silently, so a customer could be charged a
// different amount than the bill they were shown, and an expired quote was
// accepted.
//
// Covers:
//   A. services/pricing/quoteService  - signed quote ids + checkQuoteForOrder
//   B. controllers/pricingController  - the quote is bound to the customer
//   C. controllers/orderController    - the check runs before anything is created
//
// No database, no Express, no network. Usage: npm run test:quote-verification
const Module = require('module');
const path = require('path');
const fs = require('fs');
const assert = require('assert');
const ROOT = path.join(__dirname, '..');

process.env.JWT_SECRET = 'test-secret-for-quote-verification';
delete process.env.QUOTE_SIGNING_SECRET;

// ── loader with per-call stubs ─────────────────────────────────────────
function loadWith(stubs, file) {
  const target = path.join(ROOT, file);
  delete require.cache[target];
  const realLoad = Module._load;
  Module._load = function (request, parent) {
    if (Object.prototype.hasOwnProperty.call(stubs, request)) return stubs[request];
    if (parent && request.startsWith('.')) {
      const resolved = path.resolve(path.dirname(parent.filename), request);
      for (const c of [resolved, `${resolved}.js`]) {
        if (Object.prototype.hasOwnProperty.call(stubs, c)) return stubs[c];
      }
    }
    return realLoad.apply(this, arguments);
  };
  try { return require(target); } finally { Module._load = realLoad; }
}

const TTL = 10 * 60 * 1000;
const USER = '64b7f0c2a1b2c3d4e5f6071b';
const OTHER_USER = '64b7f0c2a1b2c3d4e5f6071c';
const REST = '64b7f0c2a1b2c3d4e5f60718';
const OTHER_REST = '64b7f0c2a1b2c3d4e5f6071d';
const T0 = new Date('2026-10-31T12:00:00.000Z');

let nextTotal = 12300;
let nextVersion = 'v1';
const orchestratorStub = {
  DEFAULT_QUOTE_TTL_MS: TTL,
  buildQuote: async (args) => ({
    serviceable: true,
    decision: 'PROFITABLE',
    restaurantId: String(args.restaurant?._id || ''),
    pricingVersion: nextVersion,
    quoteIssuedAt: T0.toISOString(),
    quoteExpiresAt: new Date(T0.getTime() + (args.quoteTtlMs ?? TTL)).toISOString(),
    paise: { customerTotalPaise: nextTotal },
  }),
};
const mongooseStub = { Types: { ObjectId: { isValid: (v) => /^[0-9a-fA-F]{24}$/.test(String(v)) } } };
const qs = loadWith({
  mongoose: mongooseStub,
  [path.join(ROOT, 'services/pricing/pricingOrchestrator.js')]: orchestratorStub,
}, 'services/pricing/quoteService.js');

const fresh = (over = {}) => ({ serviceable: true, pricingVersion: 'v1', paise: { customerTotalPaise: 12300 }, ...over });
const baseArgs = (quoteId, over = {}) => ({
  quoteId, userId: USER, restaurantId: REST, paymentMethod: 'upi',
  freshQuote: fresh(), hasCoupon: false, now: new Date(T0.getTime() + 60 * 1000), ...over,
});
const issue = async (over = {}) => {
  const q = await qs.createQuote({ restaurant: { _id: REST }, paymentMethod: 'upi', userId: USER, ...over });
  return q.quoteId;
};
const forge = (token, mutate) => {
  const [prefix, payload, sig] = token.split('.');
  const body = JSON.parse(Buffer.from(payload, 'base64url').toString('utf8'));
  mutate(body);
  return `${prefix}.${Buffer.from(JSON.stringify(body)).toString('base64url')}.${sig}`;
};

let failed = 0;
async function t(name, fn) {
  try { await fn(); console.log(`PASS ${name}`); } catch (err) { failed += 1; console.log(`FAIL ${name}: ${String(err.message).split('\n')[0]}`); }
}

(async () => {
  // ── A. quoteService ────────────────────────────────────────────────
  await t('A1 a quote issued for a customer carries a signed, bound quote id', async () => {
    const id = await issue();
    assert.ok(/^q2\.[\w-]+\.[\w-]+$/.test(id), `unexpected quote id format: ${id}`);
  });

  await t('A2 a quote without a customer keeps the legacy random id (admin previews)', async () => {
    const q = await qs.createQuote({ restaurant: { _id: REST }, paymentMethod: 'upi' });
    assert.ok(/^q_[0-9a-f-]{36}$/.test(q.quoteId));
  });

  await t('A3 a valid, unexpired, unchanged quote is accepted', async () => {
    const r = qs.checkQuoteForOrder(baseArgs(await issue()));
    assert.strictEqual(r.ok, true);
  });

  await t('A4 a tampered payload (cheaper total) is rejected as QUOTE_MISMATCH', async () => {
    const id = forge(await issue(), (b) => { b.t = 100; });
    const r = qs.checkQuoteForOrder(baseArgs(id, { freshQuote: fresh({ paise: { customerTotalPaise: 100 } }) }));
    assert.strictEqual(r.ok, false);
    assert.strictEqual(r.code, 'QUOTE_MISMATCH');
  });

  await t('A5 a forged expiry extension is rejected as QUOTE_MISMATCH', async () => {
    const id = forge(await issue(), (b) => { b.exp += 24 * 3600 * 1000; });
    const r = qs.checkQuoteForOrder(baseArgs(id, { now: new Date(T0.getTime() + 2 * TTL) }));
    assert.strictEqual(r.code, 'QUOTE_MISMATCH');
  });

  for (const [label, token] of [['garbage text', 'not-a-quote'], ['legacy q_ id', 'q_1b4e28ba-2fa1-11d2-883f-0016d3cca427'], ['bad signature', null], ['empty parts', 'q2..'], ['oversized', `q2.${'a'.repeat(5000)}.x`]]) {
    await t(`A6 unverifiable quote id (${label}) is rejected as QUOTE_MISMATCH`, async () => {
      const id = token === null ? `${(await issue()).slice(0, -3)}AAA` : token;
      const r = qs.checkQuoteForOrder(baseArgs(id));
      assert.strictEqual(r.ok, false);
      assert.strictEqual(r.code, 'QUOTE_MISMATCH');
    });
  }

  await t('A7 a quote issued to another customer cannot be used', async () => {
    const r = qs.checkQuoteForOrder(baseArgs(await issue({ userId: OTHER_USER })));
    assert.strictEqual(r.code, 'QUOTE_MISMATCH');
  });

  await t('A8 a quote for another restaurant cannot be used', async () => {
    const r = qs.checkQuoteForOrder(baseArgs(await issue({ restaurant: { _id: OTHER_REST } })));
    assert.strictEqual(r.code, 'QUOTE_MISMATCH');
  });

  await t('A9 a quote for UPI cannot be reused for a COD order', async () => {
    const r = qs.checkQuoteForOrder(baseArgs(await issue(), { paymentMethod: 'cod' }));
    assert.strictEqual(r.code, 'QUOTE_MISMATCH');
  });

  await t('A10 an expired quote is QUOTE_EXPIRED (and exactly at expiry is expired)', async () => {
    const id = await issue();
    assert.strictEqual(qs.checkQuoteForOrder(baseArgs(id, { now: new Date(T0.getTime() + TTL + 1) })).code, 'QUOTE_EXPIRED');
    assert.strictEqual(qs.checkQuoteForOrder(baseArgs(id, { now: new Date(T0.getTime() + TTL) })).code, 'QUOTE_EXPIRED');
    assert.strictEqual(qs.checkQuoteForOrder(baseArgs(id, { now: new Date(T0.getTime() + TTL - 1) })).ok, true);
  });

  await t('A11 a pricing-rule version change is QUOTE_PRICE_CHANGED', async () => {
    const r = qs.checkQuoteForOrder(baseArgs(await issue(), { freshQuote: fresh({ pricingVersion: 'v2' }) }));
    assert.strictEqual(r.code, 'QUOTE_PRICE_CHANGED');
  });

  await t('A12 a total that moved by more than 1 paisa is QUOTE_PRICE_CHANGED; 1 paisa is tolerated', async () => {
    const id = await issue();
    assert.strictEqual(qs.checkQuoteForOrder(baseArgs(id, { freshQuote: fresh({ paise: { customerTotalPaise: 12302 } }) })).code, 'QUOTE_PRICE_CHANGED');
    assert.strictEqual(qs.checkQuoteForOrder(baseArgs(id, { freshQuote: fresh({ paise: { customerTotalPaise: 12298 } }) })).code, 'QUOTE_PRICE_CHANGED');
    assert.strictEqual(qs.checkQuoteForOrder(baseArgs(id, { freshQuote: fresh({ paise: { customerTotalPaise: 12301 } }) })).ok, true);
  });

  await t('A13 a fresh quote that is no longer serviceable is QUOTE_PRICE_CHANGED', async () => {
    const r = qs.checkQuoteForOrder(baseArgs(await issue(), { freshQuote: fresh({ serviceable: false }) }));
    assert.strictEqual(r.code, 'QUOTE_PRICE_CHANGED');
  });

  await t('A14 with a coupon the total is not compared, but signature and expiry still are', async () => {
    const id = await issue();
    const couponFresh = fresh({ paise: { customerTotalPaise: 9000 } });
    assert.strictEqual(qs.checkQuoteForOrder(baseArgs(id, { hasCoupon: true, freshQuote: couponFresh })).ok, true);
    assert.strictEqual(qs.checkQuoteForOrder(baseArgs(id, { hasCoupon: true, freshQuote: couponFresh, now: new Date(T0.getTime() + TTL) })).code, 'QUOTE_EXPIRED');
    assert.strictEqual(qs.checkQuoteForOrder(baseArgs('junk', { hasCoupon: true, freshQuote: couponFresh })).code, 'QUOTE_MISMATCH');
  });

  await t('A15 a token signed with a different secret is rejected', async () => {
    const id = await issue();
    process.env.JWT_SECRET = 'a-different-secret';
    try { assert.strictEqual(qs.checkQuoteForOrder(baseArgs(id)).code, 'QUOTE_MISMATCH'); } finally { process.env.JWT_SECRET = 'test-secret-for-quote-verification'; }
  });

  await t('A16 with no signing secret configured, issuing fails closed and verifying rejects', async () => {
    const id = await issue();
    const saved = process.env.JWT_SECRET;
    delete process.env.JWT_SECRET;
    try {
      await assert.rejects(() => issue(), /signing secret/i);
      assert.strictEqual(qs.checkQuoteForOrder(baseArgs(id)).code, 'QUOTE_MISMATCH');
    } finally { process.env.JWT_SECRET = saved; }
  });

  await t('A17 QUOTE_SIGNING_SECRET takes precedence over JWT_SECRET', async () => {
    process.env.QUOTE_SIGNING_SECRET = 'dedicated-quote-secret';
    try {
      const id = await issue();
      assert.strictEqual(qs.checkQuoteForOrder(baseArgs(id)).ok, true);
      delete process.env.QUOTE_SIGNING_SECRET;
      assert.strictEqual(qs.checkQuoteForOrder(baseArgs(id)).code, 'QUOTE_MISMATCH');
    } finally { delete process.env.QUOTE_SIGNING_SECRET; }
  });

  await t('A18 every rejection carries a customer-safe message and no internals', async () => {
    const r = qs.checkQuoteForOrder(baseArgs(await issue(), { freshQuote: fresh({ paise: { customerTotalPaise: 99999 } }) }));
    assert.ok(r.message && r.message.length > 10);
    assert.ok(!/paise|secret|hmac|signature/i.test(r.message), 'message must not leak internals');
  });

  // ── B. the quote endpoint binds the quote to the customer ──────────
  await t('B1 POST /pricing/quote asks for a customer-bound quote id', async () => {
    let seen = null;
    const chain = (v) => ({ select() { return this; }, lean: async () => v });
    const controller = loadWith({
      mongoose: { Types: { ObjectId: { isValid: (v) => /^[0-9a-fA-F]{24}$/.test(String(v)) } } },
      'express-async-handler': (fn) => fn,
      [path.join(ROOT, 'models/Restaurant.js')]: { findOne: () => chain({ _id: REST, location: { coordinates: [88.8, 26.5] } }) },
      [path.join(ROOT, 'models/Menu.js')]: { find: () => chain([{ _id: '64b7f0c2a1b2c3d4e5f6071a', price: 100 }]) },
      [path.join(ROOT, 'models/Address.js')]: { findOne: () => chain({ location: { coordinates: [88.81, 26.51] } }) },
      [path.join(ROOT, 'models/Order.js')]: { exists: async () => null },
      [path.join(ROOT, 'services/pricing/pricingRules.js')]: { resolvePricingRules: async () => ({ version: 'v1', pricingEngineEnabled: true }) },
      [path.join(ROOT, 'services/pricing/quoteService.js')]: { createQuote: async (args) => { seen = args; return { serviceable: true, quoteId: 'x' }; } },
      [path.join(ROOT, 'services/pricing/pricingOrchestrator.js')]: { buildRestaurantCardPricing: async () => ({}) },
      [path.join(ROOT, 'services/deliveryPricing.js')]: { validCoordinates: (c) => Array.isArray(c) && c.length === 2 },
    }, 'controllers/pricingController.js');
    const res = { statusCode: 200, status(c) { this.statusCode = c; return this; }, json(b) { this.body = b; return this; }, set() { return this; } };
    await controller.quote({ user: { _id: USER }, body: { restaurantId: REST, addressId: '64b7f0c2a1b2c3d4e5f60719', items: [{ menuItem: '64b7f0c2a1b2c3d4e5f6071a', quantity: 1 }] } }, res);
    assert.strictEqual(res.statusCode, 200);
    assert.ok(seen, 'createQuote was not called');
    assert.strictEqual(String(seen.userId), USER, 'createQuote must receive the authenticated customer id');
  });

  // ── C. orderController runs the check before anything is created ───
  const orderSrc = fs.readFileSync(path.join(ROOT, 'controllers/orderController.js'), 'utf8');
  const createOrderSrc = orderSrc.slice(orderSrc.indexOf('const createOrder = asyncHandler('));

  await t('C1 createOrder reads quoteId from the request body', async () => {
    const destructure = createOrderSrc.slice(0, createOrderSrc.indexOf('} = req.body;'));
    assert.ok(/\bquoteId\b/.test(destructure), 'quoteId is not destructured from req.body');
  });

  await t('C2 createOrder verifies the quote exactly once, via quoteService.checkQuoteForOrder', async () => {
    assert.ok(/checkQuoteForOrder[^;]*require\(['"]\.\.\/services\/pricing\/quoteService['"]\)/.test(orderSrc.replace(/\s+/g, ' ')), 'checkQuoteForOrder is not imported from quoteService');
    assert.strictEqual((createOrderSrc.match(/checkQuoteForOrder\(/g) || []).length, 1);
  });

  await t('C3 the check runs after engine pricing and before the idempotency lock / any creation', async () => {
    const priced = createOrderSrc.indexOf('priceCheckoutWithEngine(');
    const check = createOrderSrc.indexOf('checkQuoteForOrder(');
    const lock = createOrderSrc.indexOf('Atomic idempotency lock');
    assert.ok(priced > 0 && check > priced, 'check must come after engine pricing');
    assert.ok(lock > check, 'check must come before the idempotency lock and order creation');
  });

  await t('C4 a failed check responds 409 with the QUOTE_* code, and only for a single-restaurant order', async () => {
    const at = createOrderSrc.indexOf('checkQuoteForOrder(');
    const win = createOrderSrc.slice(Math.max(0, at - 700), at + 900);
    assert.ok(/priced\.length\s*===\s*1/.test(win), 'verification must be limited to single-restaurant orders');
    assert.ok(/res\.status\(409\)\.json\(/.test(win), 'rejection must be a direct 409 response');
    assert.ok(/code:\s*check\.code/.test(win), 'rejection must carry the QUOTE_* code to the client');
    assert.ok(/!check\.ok/.test(win));
  });

  await t('C5 the verification only runs inside the engine-enabled branch', async () => {
    const start = createOrderSrc.indexOf('pricingRules.pricingEngineEnabled === true');
    const end = createOrderSrc.indexOf('const bills = engineQuotes');
    const check = createOrderSrc.indexOf('checkQuoteForOrder(');
    assert.ok(start > 0 && check > start && check < end, 'check must sit inside the engine branch');
  });

  await t('C6 the check is given the real customer, restaurant, payment method, fresh quote and coupon state', async () => {
    const at = createOrderSrc.indexOf('checkQuoteForOrder(');
    const call = createOrderSrc.slice(at, createOrderSrc.indexOf('});', at));
    for (const arg of ['quoteId: suppliedQuoteId', 'userId: req.user._id', 'restaurantId: priced[0].restaurant._id', 'paymentMethod: requestedMethod', 'freshQuote: engineQuotes[0]', 'hasCoupon: Boolean(couponInfo)']) {
      assert.ok(call.includes(arg), `missing argument: ${arg}`);
    }
  });

  console.log(failed ? `\n${failed} FAILED` : '\nAll quote-verification tests passed');
  process.exit(failed ? 1 : 0);
})();
